class RangeModule:
    def __init__(self):
        self.tracked = set()

    def add_range(self, left, right):
        for x in range(left, right):           # mark every individual number
            self.tracked.add(x)

    def query_range(self, left, right):
        return all(x in self.tracked for x in range(left, right))   # check every individual number

    def remove_range(self, left, right):
        for x in range(left, right):            # unmark every individual number
            self.tracked.discard(x)

