import java.util.*;

public class RangeModule {
    Set<Integer> tracked = new HashSet<>();

    void addRange(int left, int right) {
        for (int x = left; x < right; x++) tracked.add(x);      // mark every individual number
    }

    boolean queryRange(int left, int right) {
        for (int x = left; x < right; x++) if (!tracked.contains(x)) return false;  // check every number
        return true;
    }

    void removeRange(int left, int right) {
        for (int x = left; x < right; x++) tracked.remove(x);    // unmark every individual number
    }
}

