class RangeModule:
    def __init__(self):
        self.ranges = []          # sorted, merged, non-overlapping [start, end) pairs

    def add_range(self, left, right):
        res, i, n = [], 0, len(self.ranges)
        while i < n and self.ranges[i][1] < left:
            res.append(self.ranges[i]); i += 1
        new_left, new_right = left, right
        while i < n and self.ranges[i][0] <= right:      # merge every overlapping/touching range
            new_left = min(new_left, self.ranges[i][0])
            new_right = max(new_right, self.ranges[i][1])
            i += 1
        res.append([new_left, new_right])
        res.extend(self.ranges[i:])
        self.ranges = res

    def query_range(self, left, right):
        for s, e in self.ranges:
            if s <= left and right <= e:
                return True
            if s > left:
                break
        return False

    def remove_range(self, left, right):
        res = []
        for s, e in self.ranges:
            if e <= left or s >= right:
                res.append([s, e])            # untouched by the removal
                continue
            if s < left:
                res.append([s, left])           # keep the left remainder
            if e > right:
                res.append([right, e])          # keep the right remainder
        self.ranges = res

