import java.util.*;

public class RangeModule {
    List<int[]> ranges = new ArrayList<>();    // sorted, merged, non-overlapping [start, end)

    void addRange(int left, int right) {
        List<int[]> res = new ArrayList<>();
        int i = 0, n = ranges.size();
        while (i < n && ranges.get(i)[1] < left) res.add(ranges.get(i++));
        int newLeft = left, newRight = right;
        while (i < n && ranges.get(i)[0] <= right) {           // merge every overlapping/touching range
            newLeft = Math.min(newLeft, ranges.get(i)[0]);
            newRight = Math.max(newRight, ranges.get(i)[1]);
            i++;
        }
        res.add(new int[]{newLeft, newRight});
        while (i < n) res.add(ranges.get(i++));
        ranges = res;
    }

    boolean queryRange(int left, int right) {
        for (int[] r : ranges) {
            if (r[0] <= left && right <= r[1]) return true;
            if (r[0] > left) break;
        }
        return false;
    }

    void removeRange(int left, int right) {
        List<int[]> res = new ArrayList<>();
        for (int[] r : ranges) {
            if (r[1] <= left || r[0] >= right) { res.add(r); continue; }   // untouched
            if (r[0] < left) res.add(new int[]{r[0], left});                 // left remainder
            if (r[1] > right) res.add(new int[]{right, r[1]});               // right remainder
        }
        ranges = res;
    }
}

