#include <bits/stdc++.h>
using namespace std;

class RangeModule {
public:
    vector<pair<int,int>> ranges;   // sorted, merged, non-overlapping [start, end)

    void addRange(int left, int right) {
        vector<pair<int,int>> res;
        int i = 0, n = ranges.size();
        while (i < n && ranges[i].second < left) res.push_back(ranges[i++]);
        int newLeft = left, newRight = right;
        while (i < n && ranges[i].first <= right) {              // merge every overlapping/touching range
            newLeft = min(newLeft, ranges[i].first);
            newRight = max(newRight, ranges[i].second);
            i++;
        }
        res.push_back({newLeft, newRight});
        while (i < n) res.push_back(ranges[i++]);
        ranges = res;
    }

    bool queryRange(int left, int right) {
        for (auto& r : ranges) {
            if (r.first <= left && right <= r.second) return true;
            if (r.first > left) break;
        }
        return false;
    }

    void removeRange(int left, int right) {
        vector<pair<int,int>> res;
        for (auto& r : ranges) {
            if (r.second <= left || r.first >= right) { res.push_back(r); continue; }  // untouched
            if (r.first < left) res.push_back({r.first, left});                           // left remainder
            if (r.second > right) res.push_back({right, r.second});                        // right remainder
        }
        ranges = res;
    }
};
